    appr: "「野旷天低树，江清月近人」以景写愁，是唐诗中写羁旅夜泊的绝唱。",
    story: "孟浩然离开襄阳，到吴越一带漫游。他没有固定的差事，一路走走停停，靠朋友接济。有一天傍晚，他把船停在建德江边一片起雾的沙洲旁。天暗下来，岸上人家的炊烟散了，他心里那点在外漂泊的愁又冒上来。放眼望去，原野空阔，天边的树显得比天还低；江水很清，月亮的影子跟着船，离人很近。这一夜他想了什么，诗里没全说，只留下一个客居在外的人看着月亮的样子。",
