    story: "王勃在长安做朝散郎，年纪很轻。有个朋友被派到蜀地做县尉，要从长安出发，翻过秦岭去五津那一片。送行的时候他写了《送杜少府之任蜀州》。开头写长安被三秦护卫着，再写遥望蜀地的风烟。两个人都是在外面做官的人，分别本来叫人难受，他却说四海之内只要有知己，隔得再远也像挨着的邻居，不必在岔路口哭湿了手巾。这两句后来成了送别诗里最常被引用的话。王勃自己活得很短，二十几岁就去世了，留下这样的句子，一直被人记着。",
