    tr: "春江潮水与海相连，一轮明月随潮涌升起，波光荡漾千里，哪一处春江不在月明之中。江水绕过花草丛生的原野，月照花林如同落下一层雪珠。天地一色，空中只有一轮孤月。江边何年何人初见这月亮？人生一代代没有穷尽，江月年年只是相似。白云悠悠而去，离人愁绪难禁——今夜是谁家的游子在舟中，又是谁在楼上相思？月光徘徊楼上，照着她的梳妆台，卷不走、拂还来。此时彼此相望却不得相闻，但愿随着月光流照到你身边。连鸿雁也飞不出这月色，鱼龙跳跃只见水纹。昨夜梦见落花，春已过半人还未归。江水要把春天流尽，潭上落月又已西斜。斜月沉入海雾，碣石与潇湘相隔无限路途。不知有几人能乘月而归，落月摇曳的离情，洒满江边树林。",
