    story: "张若虚的生平留下的资料很少，作品传下来的也不多。相传他曾在扬州一带的江边写下这首长歌。那一夜春潮上涨，江面和海连成一片，月亮跟着潮水升起来。他写月光照在花林上，像撒了一层雪；写江畔的人第一次见到月亮是什么时候，月亮第一次照人又是什么时候。人生一代代没有尽头，江月年年看去还是一个样。接着写船上的人和楼上的人互相望不见，最后月亮斜下去，藏进海雾里。这首《春江花月夜》后来被称许为一篇压过全唐的作品。",
