    story: "王维中年以后在蓝田的辋川买下一处山间别业，住在那里半官半隐。他把辋川一带的景物逐处写成诗，一共二十首，合成《辋川集》，《鹿柴》是其中一首。鹿柴是围栏的意思，那地方山深人少。他写空山里看不见人影，却偶尔听见有人说话的声音；傍晚的日光返照进深林，又落在青苔上。二十个字，写的都是光和声音。他自己也懂画，诗里那种安静后来常被画出来。辋川的旧景今天多已难寻，这组诗倒成了后人认识那处山谷的凭据。",
