    story: "李贺身体不好，一生没到过边关，却爱写边关。他用的是乐府旧题《雁门太守行》。在他笔下，黑云压住城墙，压得快要塌下来；铠甲在日光里闪出鱼鳞一样的金光。号角声响遍秋色，血在夜里凝成紫色。红旗半卷着逼近易水，天冷霜重，连鼓声都敲不起来。最后他说，为了报答君王的知遇，愿意提剑去死。这些都不是他亲眼所见，是他从书斋里想出来的一座雁门。",
