    tr: "为何身处困窘而道义不穷？乱世与太平时的操守应当一样。家乡虽在战火之中，弟侄仍修习礼乐之风。窗外竹影摇动在书案上，野泉声流入砚池中。少年时的辛苦是终身的大事，切莫在光阴里懈怠一分功夫。",
