    appr: "以「人道」「侬道」对起，夸张风浪之高之猛，二十余字写尽横江之险，气势逼人。",
    story: "开元十四年，李白二十六岁，第一次出蜀东游。他到了历阳一带的横江浦，这里是长江上一个有名的渡口，往来的人都要从这里过江。别人都说横江好，他却说横江恶——风一刮就是三天，浪头高得盖过金陵的瓦官阁。一个人初次远行，正赶上这样的水面，印象自然深。他把这两句大白话记下来，语气像当地的船家。这组诗不止一首，他后来还写过好几首，反复说横江风浪之险。",
